const body = $json.body;
const entry = body?.entry?.[0];
const changes = entry?.changes?.[0];
const value = changes?.value;
const message = value?.messages?.[0];

if (!message?.text?.body) {
  return { json: { skip: true, from: null, text: '', phone_number_id: null } };
}

return {
  json: {
    from: message.from,
    text: message.text.body,
    phone_number_id: value.metadata.phone_number_id,
    message_id: message.id
  }
};

const systemPrompt = 'Eres un clasificador de intenciones para un chatbot de afiliaciones a seguridad social en Colombia. Devuelve UNICAMENTE un JSON valido con esta estructura: {"intent": "NOMBRE_INTENT", "confianza": "alta", "resumen": "descripcion breve"}. Intenciones: AFILIACION_NUEVA (afiliarse por primera vez), DOCUMENTOS (que documentos necesita), CAMBIO_EPS (cambiar de EPS), ESTADO_TRAMITE (consultar estado), CONSULTA_PAGO (cuanto pagar y como), MORA_DEUDA (tiene deuda), BENEFICIARIOS (agregar o quitar beneficiarios), NOVEDAD_LABORAL (cambio empleador o retiro o licencia), ESCALAR_HUMANO (quiere hablar con asesor), SALUDO_DESPEDIDA (saludo o despedida), FUERA_DE_TEMA (no relacionado al negocio). Responde SOLO con el JSON.';

let classification;
try {
  const response = await $helpers.httpRequest({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'x-api-key': $env.ANTHROPIC_API_KEY,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json'
    },
    body: JSON.stringify({
      model: 'claude-sonnet-4-6',
      max_tokens: 150,
      system: systemPrompt,
      messages: [{ role: 'user', content: $json.text }]
    })
  });
  const parsed = typeof response === 'object' ? response : JSON.parse(response);
  const text = parsed?.content?.[0]?.text || '{}';
  classification = JSON.parse(text);
} catch(e) {
  classification = { intent: 'FUERA_DE_TEMA', confianza: 'baja', resumen: 'Error al clasificar' };
}

return {
  json: {
    ...$json,
    intent: classification.intent || 'FUERA_DE_TEMA',
    confianza: classification.confianza || 'baja',
    resumen: classification.resumen || ''
  }
};

const systemPrompt = 'Eres un asistente virtual de Servicios Integrales, empresa especializada en afiliaciones a seguridad social en Colombia. Responde en espanol colombiano, tono amable y profesional. Maximo 3 parrafos cortos optimizados para WhatsApp. Cuando pregunten sobre afiliacion nueva o documentos requeridos, explica: DOCUMENTOS BASE: cedula vigente, formulario de afiliacion firmado (nosotros lo suministramos), datos de beneficiarios si aplica. TRABAJADOR DEPENDIENTE: contrato de trabajo o carta salarial, el empleador realiza los aportes. TRABAJADOR INDEPENDIENTE: RUT activo, extracto bancario o declaracion de renta, paga sobre el 40% de sus ingresos. Al finalizar solicita amablemente: nombre completo, cedula, tipo de vinculacion (dependiente o independiente) y EPS de preferencia.';

let respuesta;
try {
  const response = await $helpers.httpRequest({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'x-api-key': $env.ANTHROPIC_API_KEY,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json'
    },
    body: JSON.stringify({
      model: 'claude-sonnet-4-6',
      max_tokens: 600,
      system: systemPrompt,
      messages: [{ role: 'user', content: $json.text }]
    })
  });
  const parsed = typeof response === 'object' ? response : JSON.parse(response);
  respuesta = parsed?.content?.[0]?.text || 'Lo siento, tuve un inconveniente. Escribe ASESOR para hablar con un agente.';
} catch(e) {
  respuesta = 'Lo siento, tuve un inconveniente. Escribe ASESOR para hablar con un agente.';
}

return {
  json: {
    from: $json.from,
    phone_number_id: $json.phone_number_id,
    respuesta
  }
};

return {
  json: {
    from: $json.from,
    phone_number_id: $json.phone_number_id,
    respuesta: 'Hola! Bienvenido a *Servicios Integrales*

Soy tu asistente virtual para tramites de seguridad social en Colombia. Puedo ayudarte con:

- Afiliacion nueva (EPS, ARL, AFP, CCF)
- Documentos requeridos
- Estado de tu tramite
- Consultas de pago y aportes
- Cambio de EPS
- Novedades laborales

En que te puedo ayudar hoy?'
  }
};

return {
  json: {
    from: $json.from,
    phone_number_id: $json.phone_number_id,
    respuesta: 'Entiendo tu solicitud. Te voy a comunicar con uno de nuestros asesores especializados para que te brinde atencion personalizada.\n\nPor favor espera un momento, un asesor se comunicara contigo en breve.\n\nSi tu consulta es urgente, tambien puedes contactarnos directamente por nuestro numero de atencion al cliente.'
  }
};

return {
  json: {
    from: $json.from,
    phone_number_id: $json.phone_number_id,
    respuesta: 'Gracias por comunicarte con *Servicios Integrales*.\n\nEstoy procesando tu solicitud sobre ' + ($json.resumen || 'tu tramite') + '. Un asesor te contactara pronto para ayudarte.\n\nPuedo ayudarte con algo mas mientras tanto?'
  }
};

await $helpers.httpRequest({
  method: 'POST',
  url: 'https://graph.facebook.com/v21.0/' + $json.phone_number_id + '/messages',
  headers: {
    'Authorization': 'Bearer ' + $env.WHATSAPP_TOKEN,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({
    messaging_product: 'whatsapp',
    to: $json.from,
    type: 'text',
    text: { body: $json.respuesta }
  })
});

return { json: { status: 'sent', to: $json.from } };
